   !> Nonlocal PCM (gaussian charges): build the cavity operators
   !>
   !> - Vectors have length npt, matrices are (npt, npt), point fields (3, npt)
   !> - Outputs are undefined if error is allocated
   !>
   !> @param[in,out] state  state of nonlocal_pcm
   !> @param[in] r  positions of the surface points
   !> @param[in] n  outward unit normals at the surface points
   !> @param[in] k1  first principal curvature (positive where convex)
   !> @param[in] k2  second principal curvature (positive where convex)
   !> @param[in] xi  gaussian widths of the surface charges (ISWIG: xi_Born/(R_I sqrt(w_i)))
   !> @param[in] F  switching function (1 where the grid is not switched)
   !> @param[in] a  grid point areas
   !> @param[out] error  error handling; allocated on failure
   !> @param[in] solver  linear solver, copied into the state; default dense LAPACK (Cholesky,
   !> symmetric or LU)
   subroutine nonlocal_pcm_mf_assemble(state, r, n, k1, k2, xi, F, a, error, solver)
      !> State of nonlocal_pcm
      type(nonlocal_pcm_state), target, intent(inout) :: state
      !> Positions of the surface points
      real(wp), contiguous, intent(in) :: r(:, :)
      !> Outward unit normals at the surface points
      real(wp), contiguous, intent(in) :: n(:, :)
      !> First principal curvature (positive where convex)
      real(wp), contiguous, intent(in) :: k1(:)
      !> Second principal curvature (positive where convex)
      real(wp), contiguous, intent(in) :: k2(:)
      !> Gaussian widths of the surface charges (ISWIG: xi_Born/(R_I sqrt(w_i)))
      real(wp), contiguous, intent(in) :: xi(:)
      !> Switching function (1 where the grid is not switched)
      real(wp), contiguous, intent(in) :: F(:)
      !> Grid point areas
      real(wp), contiguous, intent(in) :: a(:)
      !> Error handling
      type(error_type), allocatable, intent(out) :: error
      !> Linear solver
      class(pcm_solver), intent(in), optional :: solver

      integer :: npt
      integer :: stat

      stat = 0
      npt = size(r, 2)
      if (npt < 1) then
         call fatal_error(error, "[nonlocal_pcm_mf_assemble] empty discretization")
         return
